SELECT id, COALESCE(NULL * CAST(a AS DECIMAL(10,2)), CAST(a AS DECIMAL(10,2))) = 5 AS c5, NULL * CAST(a AS DECIMAL(10,2)) * 2 IS NULL AS m, CAST(a AS DECIMAL(10,2)) * NULL + CAST(a AS DECIMAL(10,2)) IS NULL AS s, CASE WHEN a > 0 THEN NULL * CAST(a AS DECIMAL(10,2)) ELSE CAST(a AS DECIMAL(10,2)) END = 0 AS e FROM t ORDER BY id;
